\phantomsection
\label{ass:affine-seed}
\begin{enumerate}
\item[(i)] $G_1$ has finite moments of all orders, with mean normalized so that
$a'(0)=1$ and with positive variance {$\sigma^2:=-a''(0)>0$}.
\item[(ii)] One of the following two activity conditions holds:
  \begin{enumerate}
  \item[(a)] \(G_1(\{0\})>0\) (the finite-activity case);
  \item[(b)] \(G_1(\{0\})=0\), but for every \(m>0\), \(G_m\) has a density \(g(m,x)\) such
  that \((m,x)\mapsto g(m,x)\) is jointly continuous and strictly
  positive on \((0,\infty)^2\) (the infinite-activity positive-density
  case).
  \end{enumerate}
\end{enumerate}

\label{thm:affine-boundary}
Suppose Assumptions~\ref{ass:affine-seed} and
\ref{ass:invertibility} hold and \(\phi=1\), so that
\(\alpha=1-\beta>0\).
\begin{enumerate}
\item If \(\omega<0\), the state recursion $(M_t)$, as well as the process
$(X_t)$, has a unique stationary distribution satisfying $\Pr(M_0>y)\sim Cy^{-\kappa},\qquad y\to\infty,$ where $C$ is a positive constant and \(\kappa:=-2\omega/(\alpha^2\sigma^2)\).   
For every \(s>0\), the moments \(\mathbb{E} M_0^s\) and \(\mathbb{E} X_0^s\) are finite
if and only if \(s<\kappa\).  Furthermore,
\begin{itemize}
\item $(X_t)$ is not exponentially \(\beta\)-mixing.
\item If
\(\kappa>1\), then for any exponent \(r\) satisfying \(1<r<\kappa\),
\(j^r\beta_X^{\mathrm{mix}}(j)\) converges to zero as \(j\) increases to infinity.
\item The process is covariance stationary if and only if \(\kappa>2\).
\end{itemize}
\item If \(\omega\geq0\), the process $(X_t)$ has no stationary distribution.

\end{enumerate}

\label{thm:kappa-two-three-long-memory}
Suppose Assumptions~\ref{ass:affine-seed} and
\ref{ass:invertibility} hold, with \(\phi=1\) and \(\omega<0\), and let
\(\kappa\) be as in Theorem~\ref{thm:affine-boundary}.
\begin{enumerate}
\item If \(\kappa>3\), then \((\rho_X(j))\) is absolutely summable.
\item If \(2<\kappa\leq3\) and \(\beta\geq0\), then \((X_t)\) has long memory:
\(\rho_X(j)\geq0\) for all \(j\), and for some \(C>0\),
\(\rho_X(j)\geq Cj^{-(\kappa-2)}\) for all sufficiently large \(j\).
Consequently,
\begin{equation}
 \sum_{j=0}^{\infty}\rho_X(j)=\infty.
\label{eq:kappa-two-three-acf-divergence}
\end{equation}
\end{enumerate}

\label{thm:rootn-local-power}
Suppose that the conditions of Theorem~\ref{thm:affine-qmle} hold at
\(\theta_0\), the conditional distribution is Poisson (hence \(\sigma_0^2=1\)),
and \(\kappa_0>1\).
For each sufficiently large \(n\), let
\(\{(M_{n,t},X_{n,t}):t\in\mathbb Z\}\) be a two-sided stationary row at
\(\theta_n\), and let \(\pi_n\) be the invariant law of its state chain;
thus \(M_{n,0}\sim\pi_n\).  Let \(\pi_0\) denote the invariant law of the
state chain at \(\theta_0\).  This data-generating initialization is
distinct from the fixed, parameter-independent filter initialization used to
compute the QMLE in \eqref{eq:affine-qmle-criterion}.  Then
\begin{equation}
 \pi_n\Rightarrow\pi_0.
 \label{eq:rootn-local-invariant-convergence}
\end{equation}
Moreover,
\begin{equation}
 \sqrt n(\widehat\theta_n-\theta_n)
 \Rightarrow N(0,I_0^{-1}),
 \qquad
 \widehat I_{Q,n}\xrightarrow{p}I_0,
 \qquad
 \widehat\sigma_n^2\xrightarrow{p}1.
 \label{eq:rootn-local-estimator}
\end{equation}
Then the Wald statistic defined in Section~\ref{sec:unit-root-test} satisfies
\begin{equation}
 T_n\Rightarrow
 N\left(-\frac{h}{\tau_{\phi,0}},1\right),
 \label{eq:rootn-local-wald}
\end{equation}
where the scale defined in Section~\ref{sec:unit-root-test} satisfies
\(\tau_{\phi,0}^2=e_\phi^\top I_0^{-1}e_\phi\) because \(\sigma_0^2=1\).
Consequently, the level-\(\eta\) test that rejects when
\(T_n<z_\eta\) has limiting power
\begin{equation}
 \Phi\left(z_\eta+\frac{h}{\tau_{\phi,0}}\right).
 \label{eq:rootn-local-power}
\end{equation}

\label{lem:affine-state-observation-moments}
Under Assumption~\ref{ass:affine-seed}, if \(X\mid M=m\sim G_m\), then,
for every \(s>0\), \(\mathbb{E} X^s<\infty\) if and only if \(\mathbb{E} M^s<\infty\).

\label{lem:affine-cancellation}
For every \(\chi>0\), as \(m\to\infty\),
\[
 \frac{\mathbb{E}\!\left[s_c(\omega+\alpha W_m+\beta m)^{\chi}\right]}{m^\chi}
 \longrightarrow\bigl[\max(\phi,0)\bigr]^{\chi}.
\]

\label{lem:finite-activity-wasserstein-coupling}
Suppose Assumptions~\ref{ass:affine-seed} and \ref{ass:invertibility}
hold through the finite-activity alternative.  On \(E=[0,\infty)\),
with \(G_0=\delta_0\), the state kernel \(P\) has at most one invariant
probability.  There are a bounded complete metric \(d\), generating the
usual topology, and a coupling kernel \(Q\) for \(P\) such that
\(Qd\leq d\), with strict contraction when \(d<1\).  For every
\(R<\infty\), there are \(N_R\geq1\) and \(\delta_R>0\) such that
\begin{equation}
 (Q^{N_R}d)(m,m')\leq(1-\delta_R)d(m,m'),
 \qquad (m,m')\in[0,R]^2.
 \label{eq:finite-activity-coupling-set}
\end{equation}
If \(\pi\) is invariant, the stationary observations satisfy
\begin{equation}
 \beta_X^{\rm mix}(n)
 \leq C\int\mathcal W_d(P^{n-1}(m,\cdot),\pi)\,\pi(dm),
 \qquad n\geq1,
 \label{eq:finite-activity-wasserstein-beta}
\end{equation}
where \(\mathcal W_d\) is the infimum of the expected distance \(d\)
over couplings of its two arguments.

\label{lem:affine-boundary-invariant-tail}
Suppose Assumptions~\ref{ass:affine-seed} and
\ref{ass:invertibility} hold, with \(\phi=1\), \(\omega<0\), and
\(\kappa=-2\omega/(\alpha^2\sigma^2)\).  Under any invariant probability
law, there is a constant \(C>0\) such that
\begin{equation}
 \Pr(M_0>y)\sim Cy^{-\kappa},\qquad y\to\infty.
 \label{eq:affine-boundary-state-tail}
\end{equation}
Consequently, for every \(s>0\), the moments \(\mathbb{E} M_0^s\) and
\(\mathbb{E} X_0^s\) are finite if and only if \(s<\kappa\).

\label{lem:kappa-two-three-persistence}
There are \(a_{\rm per},p_{\rm per},m_0>0\) such that, for every
\(m\geq m_0\) and every integer \(0\leq j\leq a_{\rm per}m\),
\begin{equation}
 \Pr(M_k\in[m/2,2m]\text{ for all }0\leq k\leq j,\,
             X_0\geq m/2,\ X_j\geq m/4\mid M_0=m)\geq p_{\rm per}.
 \label{eq:kappa-two-three-persistence}
\end{equation}

\label{lem:boundary-qmle-hessian-envelope}
Under the assumptions of Theorem~\ref{thm:affine-qmle}, suppose that
\(\phi_0=1\) and \(\mathbb{E} M_t<\infty\).  Use the inference notation from
Section~\ref{app:inference-notation}.  There is a compact convex
neighborhood \(\mathcal N\subseteq\operatorname{int}(\Theta_Q)\)
of \(\theta_0\) such that
\begin{equation}
 \mathbb{E}\sup_{\theta\in \mathcal N}
 \|\partial_{\theta\theta^\top}^2\ell_t^Q(\theta)\|<\infty,
 \qquad
 \mathbb{E}\sup_{\theta\in \mathcal N}
 \frac{\|D_t(\theta)\|^2}{M_t(\theta)}<\infty.
 \label{eq:qmle-boundary-local-envelopes}
\end{equation}
